#!/usr/bin/env node
// tier: T2
/**
 * build-state-inject.mjs — UserPromptSubmit + SessionStart hook.
 *
 * Permanent-memory anchor for "what's already built / what needs wiring /
 * what's still pending / what's awaiting frontend merge". Reads the
 * compact BUILD_STATE.json snapshot generated by
 * scripts/build-state-snapshot.mjs and injects a token-bounded summary
 * (≤500 tokens) so every Claude session sees the same ground truth.
 *
 * Why this hook exists:
 *   - Roadmap envelopes drift (status:not_started even after units ship).
 *   - Audit chats over-report gaps because they don't see what's already
 *     wired.
 *   - 898 engines on disk currently have no dispatcher reference — every
 *     chat needs to know that wiring backlog exists before they propose
 *     building yet another engine.
 *   - 2 codex frontend builds are awaiting merge into mcp-server/web.
 *     Without surfacing this, the next frontend chat re-derives the gap.
 *
 * Triggers:
 *   - SessionStart: always inject (one-shot per session).
 *   - UserPromptSubmit: keyword-gated. Inject when prompt mentions
 *       build|wiring|merge|frontend|orphan|unwired|audit|roadmap|
 *       milestone|status|state|progress|inventory.
 *
 * Fail-safe: continueOnError. Skips silently on any error so a broken
 * BUILD_STATE never blocks the session.
 *
 * Regenerate the underlying snapshot:
 *   node H:/prism/scripts/build-state-snapshot.mjs
 *
 * Disable: PRISM_BUILD_STATE_INJECT=0
 */

import { existsSync, readFileSync, statSync } from "node:fs";
import { spawnSync } from "node:child_process";
import path from "node:path";
// 2026-05-26 (U-D9-CLAUDE-MD-COUNTER-WIRE, slot:alpha): S6 shared counter for
// FEATURE-UTILIZATION dashboard. CLAUDE_md was 0-fire because no per-prompt
// hook reads it (it's auto-loaded by the harness). This SessionStart-context
// hook fires once per session start, which is exactly when CLAUDE.md is
// loaded into the prompt — so counting fires here = counting CLAUDE.md loads.
import { incrementFeature } from "../helpers/feature-counter.mjs";

// Optional — we soft-import the hook-profile helper so this hook is still
// usable in setups where the helper is missing.
let _hp_shouldSkip = async () => false;
try {
  ({ shouldSkipHook: _hp_shouldSkip } = await import(
    "../helpers/hook-profile.mjs"
  ));
} catch {
  /* no-op */
}

const REPO_ROOT = "H:/prism";
const SNAPSHOT = path.join(REPO_ROOT, "state/shared/BUILD_STATE.json");
const GEN = path.join(REPO_ROOT, "scripts/build-state-snapshot.mjs");

const STALENESS_HOURS = 12; // Snapshot must be fresh.
const MAX_INJECT_CHARS = 1800; // Token-bound. ~450 tokens.

const KEYWORDS =
  /\b(build(?:ing)?|wiring|merge|frontend|orphan|unwired|audit|roadmap|milestone|status|state|progress|inventory|pending|gap)\b/i;

function readStdin() {
  try {
    return readFileSync(0, "utf8");
  } catch {
    return "";
  }
}

function ageHours(p) {
  if (!existsSync(p)) return Infinity;
  return (Date.now() - statSync(p).mtimeMs) / (1000 * 60 * 60);
}

function regenerateIfStale() {
  if (ageHours(SNAPSHOT) <= STALENESS_HOURS) return;
  const node = process.execPath || "node";
  spawnSync(node, [GEN], {
    timeout: 30_000,
    stdio: "ignore",
  });
}

function emit(eventName, additionalContext) {
  process.stdout.write(
    JSON.stringify({
      continue: true,
      hookSpecificOutput: {
        hookEventName: eventName,
        additionalContext,
      },
    }),
  );
}

function summarize(snapshot) {
  const h = snapshot.headline ?? {};
  const wireDomains = (snapshot.NEEDS_WIRING?.top_domains ?? []).slice(0, 5);
  const drift = snapshot.NEEDS_BUILDING?.drift_cases ?? [];
  const fronts = snapshot.NEEDS_FRONTEND?.trees ?? [];
  const pendingFronts = fronts.filter(
    (f) => f.merge_status === "PENDING_MERGE",
  );

  const lines = [];
  lines.push("## 🧭 BUILD_STATE — what's built / wiring / pending / frontend (auto-injected)");
  lines.push("");
  lines.push(
    `**${h.built_engines ?? "?"} engines wired** · **${h.needs_wiring ?? "?"} unwired** · **${h.needs_building_active_units ?? "?"} units pending across ${h.pending_milestones_with_activity ?? "?"} active milestones** · **${h.needs_frontend_merge_count ?? 0} frontend(s) awaiting merge** · **${h.drift_milestones ?? 0} envelope drift**`,
  );
  lines.push("");

  if (wireDomains.length) {
    lines.push("**Top unwired domains:** " +
      wireDomains.map((d) => `${d.domain} (${d.count})`).join(", "));
    lines.push("");
  }

  if (drift.length) {
    lines.push("**Envelope drift (claim vs git):**");
    for (const d of drift.slice(0, 4)) {
      lines.push(`- \`${d.id}\`: claims **${d.claimed}**, real **${d.real}**`);
    }
    lines.push("");
  }

  if (pendingFronts.length) {
    lines.push("**Frontend merges pending:**");
    for (const f of pendingFronts) {
      lines.push(`- \`${f.path}\` — ${f.stack} (${f.id})`);
    }
    lines.push("");
  }

  lines.push(
    "Full data: `state/shared/BUILD_STATE.json` · Human view: `state/shared/BUILD_STATE.md` · Regen: `node scripts/build-state-snapshot.mjs`",
  );

  let body = lines.join("\n");
  if (body.length > MAX_INJECT_CHARS) {
    body = body.slice(0, MAX_INJECT_CHARS - 12) + "\n…(truncated)";
  }
  return body;
}

(async () => {
  if (process.env.PRISM_BUILD_STATE_INJECT === "0") process.exit(0);
  if (await _hp_shouldSkip("build-state-inject")) process.exit(0);

  // U-D9: feature engaged — SessionStart fired, CLAUDE.md is being loaded into context.
  try { incrementFeature("CLAUDE_md", { slot: null }); } catch { /* never blocks */ }

  try {
    const stdin = readStdin();
    let event = null;
    let prompt = "";
    try {
      const data = stdin ? JSON.parse(stdin) : {};
      event = data?.hook_event_name || data?.hookEventName || null;
      prompt = data?.user_prompt || data?.prompt || "";
    } catch {
      /* no payload — assume SessionStart */
    }

    const isSessionStart = event === "SessionStart" || event === null;
    const isPromptSubmit = event === "UserPromptSubmit";

    if (isPromptSubmit && !KEYWORDS.test(prompt)) {
      // Out-of-band prompt — don't pay the inject cost.
      process.exit(0);
    }

    regenerateIfStale();

    if (!existsSync(SNAPSHOT)) {
      emit(
        event ?? "SessionStart",
        "⚠ BUILD_STATE.json missing — run `node H:/prism/scripts/build-state-snapshot.mjs`.",
      );
      process.exit(0);
    }

    // 2026-05-19 [GOLF]/U-WAVE2B: optional pointer mode preserves the regen
    // discipline (file stays fresh on disk) while skipping the ~950B summary
    // inject. Default behavior unchanged. Modes:
    //   summary (default) — legacy 1.8KB-cap summary
    //   pointer           — 4-line pointer at the file
    //   silent            — no inject (regen still runs)
    const mode = String(process.env.PRISM_BUILD_STATE_INJECT_MODE || "summary").toLowerCase();
    if (mode === "silent") process.exit(0);
    if (mode === "pointer") {
      const ageH = (Date.now() - statSync(SNAPSHOT).mtimeMs) / 3600_000;
      const ageStr = ageH < 1 ? `${Math.round(ageH * 60)}m` : ageH < 48 ? `${Math.round(ageH)}h` : `${Math.round(ageH / 24)}d`;
      emit(event ?? "SessionStart", [
        "## 🧭 PRISM BUILD_STATE — auto-regenerated snapshot on disk (pointer mode)",
        `   📍 \`state/shared/BUILD_STATE.md\` (age: ${ageStr}, regenerates ≤${STALENESS_HOURS}h) — engines wired/unwired · pending units · envelope drift · frontend merges`,
        "   Read this file for the full snapshot. Modes: unset `PRISM_BUILD_STATE_INJECT_MODE` (default) or `=summary`. Silence: `=silent`.",
      ].join("\n"));
      process.exit(0);
    }

    const snap = JSON.parse(readFileSync(SNAPSHOT, "utf8"));
    emit(event ?? "SessionStart", summarize(snap));
    process.exit(0);
  } catch {
    // Fail-open. The session must never break because BUILD_STATE is broken.
    process.exit(0);
  }
})();
